final class Counter implements Runnable {
    private static final Object STOP = new Object();
    private final BlockingQueue<Object> mailbox = new ArrayBlockingQueue<>(1_000);
    private int count;                              // touched only by run()
    void tell(int delta) throws InterruptedException { mailbox.put(delta); }
    void stop() throws InterruptedException { mailbox.put(STOP); }
    public void run() {
        try { while (true) { Object msg = mailbox.take(); if (msg == STOP) return; count += (Integer) msg; } }
        catch (InterruptedException e) { Thread.currentThread().interrupt(); }
    }
}

