public class Counter extends AbstractBehavior<Counter.Add> {
    public record Add(int n) {}
    private int count;
    public Receive<Add> createReceive() {
        return newReceiveBuilder().onMessage(Add.class, this::onAdd).build();
    }
    private Behavior<Add> onAdd(Add m) { count += m.n(); return this; }  // no locks needed
    public static Behavior<Add> create() { return Behaviors.setup(Counter::new); }
}

